  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED brought cavity quantum electrodynamics into a solid-state platform, enabling strong coupling between microwave photons and engineered atoms and opening a major route to quantum information experiments.",
        "attribution": "Blais established the theoretical architecture; Schoelkopf's group realized key experiments, with Wallraff leading landmark demonstrations. This is a collective development, and priority and credit across the broader community require care.",
        "maturity": "The basic phenomena and platform have been reproduced and developed across many laboratories for over two decades. Its fundamental impact is clear even though fault-tolerant computing remains unfinished.",
        "uncertainties": [
          "The discovery spans theory, first demonstrations, and later technical advances, making a three-person attribution boundary difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B050",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "The trapped-ion proposal for quantum logic and its experimental realization established a precise, scalable paradigm for controlling individual quantum systems and testing quantum information ideas.",
        "attribution": "Cirac and Zoller supplied seminal theory, while Blatt's experiments demonstrated and extended ion-trap quantum logic. The theory and experimental realization are complementary contributions.",
        "maturity": "The approach has sustained experimental confirmation and significant growth across laboratories. A practical fault-tolerant machine is still under development, but that does not diminish the foundational achievement.",
        "uncertainties": [
          "Many groups contributed to the maturation of trapped-ion control and computing after the initial proposal and demonstrations."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks turned ultranarrow optical transitions into exceptionally stable and accurate time standards, with broad consequences for precision measurement and tests of fundamental physics.",
        "attribution": "Katori developed the lattice clock concept and key demonstrations; Ye made major independent advances in clock realization and precision. Their distinct contributions are both central.",
        "maturity": "The technique is robust, independently pursued, and has achieved extraordinary reproducibility and accuracy. Its scientific and metrological impact is already established.",
        "uncertainties": [
          "The field's later advances involve many groups, so the prize would need to focus on the invention and early realization."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and photonic band gaps introduced a powerful way to control light propagation through periodic structures, shaping nanophotonics and enabling new optical devices.",
        "attribution": "Yablonovitch and John independently articulated the photonic band-gap concept, while Joannopoulos developed influential theory and design methods. Russell and Noda made major related advances in distinct implementations.",
        "maturity": "The underlying physics is well established and the ideas have been realized across numerous materials and device types.",
        "uncertainties": [
          "The broad label combines foundational proposals with several technically distinct lines of development."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Eugene S. Polzik",
        "H. Jeff Kimble",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Light-matter interfaces and quantum memories made it possible to map photonic quantum states to matter and retrieve them, supplying essential physical ingredients for quantum communication and networking.",
        "attribution": "Kimble, Polzik, and Lukin led influential, complementary approaches to quantum interfaces and memories. The broad area has many contributions, so attribution should be tied to specific foundational demonstrations.",
        "maturity": "Storage and retrieval of quantum states have been demonstrated in multiple physical systems, though performance and networking at useful scale remain active challenges.",
        "uncertainties": [
          "The discovery description covers a wide set of protocols and material platforms with overlapping contributors."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B049",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light enabled measurements beyond the standard quantum limit and is now a powerful tool in precision interferometry, including gravitational-wave detection.",
        "attribution": "Caves established the theoretical framework for quantum-enhanced interferometry; Kimble's work advanced optical squeezing experiments, and Schnabel contributed to precision implementations. The path from theory to large-scale use involved a broad community.",
        "maturity": "Squeezing is reproducible and has demonstrated concrete value in operating interferometers. Its foundational and practical significance is well confirmed.",
        "uncertainties": [
          "Credit for the development and deployment of squeezed-light sources is distributed across many theorists and experimental teams."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Daniel Loss",
        "David P. DiVincenzo",
        "Lieven M. K. Vandersypen"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum-dot spin-qubit proposal identified a route to quantum information processing using semiconductor technology, and experiments established coherent control of individual spins.",
        "attribution": "Loss and DiVincenzo provided the influential proposal and criteria; Vandersypen led important demonstrations of coherent control and multi-qubit operations. The later field includes extensive contributions from other groups.",
        "maturity": "Spin qubits have advanced substantially, with repeated demonstrations of control and improved coherence, but scalable operation remains an open engineering and physics challenge.",
        "uncertainties": [
          "The boundary between the original proposal and the broader development of semiconductor spin qubits is not sharp."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "John D. Teufel",
        "Markus Aspelmeyer"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of mechanical oscillators brought engineered mesoscopic motion into the quantum regime, probing the boundary between quantum and classical behavior.",
        "attribution": "Cleland, Teufel, and Aspelmeyer made major contributions through distinct circuit, microwave, and optical approaches. The advance is inherently international and distributed across several experimental groups.",
        "maturity": "Ground-state preparation and quantum control have been demonstrated in multiple platforms, but robust, widely replicated control of larger mechanical systems is still developing.",
        "uncertainties": [
          "The field continues to evolve, and it is not yet clear which demonstrations will define its lasting foundational contribution."
        ]
      }
    }
  ]
}
